using System.Text;
using LWS.TruckSports;
using LWS.TruckBowling;
using UnityEngine;
using UnityEngine.InputSystem;
namespace LWS.TruckSubmarine {
 public sealed class SubmarineMatch:SportsEventSession {
  public SubmarineDiver[] divers;public SubmarineCargo[] treasures;public SubmarineBuoy buoy;public SportsDrivingViews drivingViews;public SportsEventCamera broadcast;public SubmarinePresentation presentation;public SubmarineRules rules=new SubmarineRules();
  public Key[] ascendKeys={Key.Q,Key.PageUp,Key.Y,Key.O},descendKeys={Key.E,Key.PageDown,Key.B,Key.Semicolon},sonarKeys={Key.C,Key.RightCtrl,Key.V,Key.P};
  public int NativeDeliveries{get;private set;}public int AIPlans{get;private set;}public int LastDeliveredOwner{get;private set;}=-1;
  readonly float[] nextPlan=new float[4];readonly int[] target={-1,-1,-1,-1},patrol=new int[4];readonly bool[] extrasReleased=new bool[4];readonly Vector3[] goals=new Vector3[4];readonly RaycastHit[] obstacles=new RaycastHit[24];readonly StringBuilder results=new StringBuilder(300);
  static readonly Vector3[] Patrol={new Vector3(-45,-38,-70),new Vector3(40,-65,0),new Vector3(95,-95,65),new Vector3(0,-130,120),new Vector3(-110,-85,55),new Vector3(-70,-45,-50)};
  public override string Title=>"TRUCK SUBMARINE";public override int MinimumPlayers=>1;public override int MaximumPlayers=>4;public override int WeatherCount=>1;public override bool SupportsSplitAIViews=>true;public override bool CompactBroadcastStatus=>true;public override bool CompactViewportHud=>true;public override Vector2 ViewportCardAnchor(int view,Rect viewport)=>new Vector2(0,1);public override int CompactScoreColumns=>4;public override bool MultiViewHUD=>drivingViews!=null&&!drivingViews.NeedsArena;
  public override string OptionLabel=>option==0?"COASTAL · 3 MIN · 90m RATED":option==1?"DEEP SURVEY · 4 MIN · 120m RATED":"ABYSS · 5 MIN · 150m RATED";
  public override string Header=>Title+" · "+(rules.Phase==SubmarinePhase.Ready?"DIVE IN "+Mathf.CeilToInt(3-rules.Clock):Mathf.CeilToInt(rules.Remaining)+"s");
  public override string Status=>rules.Phase==SubmarinePhase.Ready?"READY · BUOYANCY CHECK":rules.Complete?"":"DELIVERED "+NativeDeliveries+" / "+SubmarineRules.CargoCapacity+" · BUOY "+Mathf.CeilToInt(-buoy.transform.position.y)+"m";
  public override string Help=>"Explore an ocean trench in your full-sized NWH truck. Archimeds supplies buoyancy and water drag; propellers steer and propel. Drive/steer retain configured keys and triggers. Keyboard ASCEND/DESCEND/SONAR: player1 Q/E/C; player2 PageUp/PageDown/RightCtrl; player3 Y/B/V; player4 O/semicolon/P. Hold SONAR with altitude controls to adjust ballast. Whole controller: RT/LT forward/reverse, left stick steer, RB/LB ascend/descend, D-pad up/down adds/removes ballast, D-pad left/right roll trim, West sonar; right stick retains cab free-look. Shared-controller halves: own shoulder ascends, own stick-click descends, own trigger ACTION; hold trigger with altitude control for ballast. Physical pitch/roll correction keeps the truck upright. ACTION grabs treasure actually touching the front cradle; while carrying it releases physical cargo; when empty away from cargo it pulses sonar. Sonar discovers real treasure within85m, cooldown4seconds. Only carried cargo physically delivered inside the lit reception cage under the surface buoy scores. Chests30, gold50, artifacts40, cargo25, salvage20 multiply by original depth: every45m adds one tier, at most4x. Pickup and sonar score nothing. Pressure damages hull beyond rated depth; ascend to recover. Hull failure retires in place and drops cargo, never teleports. AI swims, scans, grabs and delivers with the same gates. Rare giant squid encounters are animated. Timed matches rank delivered points with shared ties. Shared/chase/cab, pause, profiles, disconnect handling and rematch retain original controls.";
  public override bool BroadcastParticipantActive(int slot)=>slot>=0&&slot<setup.count&&!rules.retired[slot];public override float ParticipantProgress(int slot)=>-1;
  public override bool TryReadScoreCard(int slot,out string score,out string detail){bool valid=slot>=0&&slot<setup.count;score=valid?rules.points[slot]+" PTS":"";detail=valid?rules.deliveries[slot]+" DELIVERIES"+(MultiViewHUD?"":" · "+Mathf.CeilToInt(rules.integrity[slot])+"% HULL"):"";return valid;}
  public override bool TryReadViewportCard(int view,out int participant,out string score,out string detail)=>TryReadDrivingViewportCard(drivingViews,view,out participant,out score,out detail);
  public override string ViewportTelemetry(int view)=>Readout(drivingViews.rally.owners[view]);
  public override string ViewText(int view){int slot=drivingViews.rally.owners[view];return setup.players[slot].name+" · "+rules.points[slot]+" PTS\n"+Readout(slot);}
  public string Readout(int slot){if(slot<0||slot>=setup.count)return "";var d=divers[slot];return rules.retired[slot]?"PRESSURE FAILURE":Mathf.Max(0,-d.truck.body.position.y).ToString("F0")+"m · "+Mathf.CeilToInt(rules.integrity[slot])+"% HULL · "+(d.Carrying!=null?"CARGO → BUOY":"SONAR "+d.SonarPulses)+" · BALLAST "+d.Ballast.ToString("+0.0;-0.0;0");}
  public override string Standings{get{results.Clear();for(int place=1;place<=setup.count;place++)for(int i=0;i<setup.count;i++)if(rules.Place(i)==place)results.Append('#').Append(place).Append(' ').Append(setup.players[i].name).Append(" · ").Append(rules.points[i]).Append(" PTS · ").Append(rules.deliveries[i]).Append(" DELIVERIES · ").Append(Mathf.RoundToInt(rules.deepest[i])).Append("m\n");return results.ToString();}}
  public override string Results=>"SALVAGE EXPEDITION COMPLETE\nOnly delivered treasure scores.\n\n"+Standings;
  public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;for(int i=0;i<setup.count;i++){if(setup.players[i].source!=BowlingSource.Keyboard)continue;foreach(var key in new[]{ascendKeys[i],descendKeys[i],sonarKeys[i]}){if(key==Key.None||key==Key.Escape){reason="Assign distinct submarine keys; Escape remains pause.";return false;}for(int j=0;j<setup.count;j++){var p=setup.players[j];if(p.source!=BowlingSource.Keyboard)continue;if(key==p.forward||key==p.back||key==p.left||key==p.right||key==actionKeys[j]){reason="Submarine key conflicts with driver "+(j+1);return false;}if(j!=i&&(key==ascendKeys[j]||key==descendKeys[j]||key==sonarKeys[j])){reason="Submarine keys must be unique between keyboard drivers.";return false;}}}if(ascendKeys[i]==descendKeys[i]||ascendKeys[i]==sonarKeys[i]||descendKeys[i]==sonarKeys[i]){reason="Altitude and sonar keys must differ.";return false;}}return true;}
  protected override void BeginGame(){if(divers==null||divers.Length!=4||treasures==null||treasures.Length!=25||buoy==null||drivingViews==null||presentation==null)throw new System.InvalidOperationException("Author the complete four-truck submarine expedition.");rules.Reset(setup.count,Mathf.Clamp(option,0,2));NativeDeliveries=AIPlans=0;LastDeliveredOwner=-1;for(int i=0;i<4;i++){divers[i].Drop();divers[i].gameObject.SetActive(i<setup.count);target[i]=-1;patrol[i]=i%Patrol.Length;nextPlan[i]=0;extrasReleased[i]=false;if(i<setup.count)divers[i].Prepare(new Vector3((i-1.5f)*12,-12,-145),Quaternion.identity);}foreach(var cargo in treasures)cargo.ResetCargo();Physics.SyncTransforms();drivingViews.Layout();presentation.ResetExpedition(MatchId);}
  protected override void Simulate(float dt){rules.Tick(dt);if(rules.Complete){for(int i=0;i<setup.count;i++)if(rules.Place(i)==1)ConfirmOutcome("expedition:"+i,i,rules.points[i],"SALVAGE CHAMPION","PTS",SportsScoreTier.MatchChampion,matchEnded:true);EndMatch();return;}if(rules.Phase==SubmarinePhase.Ready){for(int i=0;i<setup.count;i++)divers[i].truck.TickDrive(Vector2.zero);return;}
   for(int i=0;i<setup.count;i++){var d=divers[i];if(rules.retired[i])continue;if(rules.Pressure(i,-d.truck.body.position.y,dt)){d.Freeze();feedback.PlayAt(4,d.truck.body.position,0,true);continue;}
    Vector2 drive;float vertical,ballast=0,roll=0;bool sonar=false;bool action=actions[i];
    if(setup.players[i].source==BowlingSource.AI){drive=Bot(i,dt,out vertical);ballast=Mathf.Abs(vertical)>.9f?-vertical*.15f:-d.Ballast*.5f;if(d.Carrying==null){d.Sonar();if(target[i]>=0&&d.GrabNearest())target[i]=-1;}}
    else{drive=commands[i];ReadControls(i,out vertical,out ballast,out roll,out sonar);if(!extrasReleased[i]){if(Mathf.Abs(vertical)+Mathf.Abs(ballast)+Mathf.Abs(roll)<.01f&&!sonar)extrasReleased[i]=true;vertical=ballast=roll=0;sonar=false;}if(sonar)d.Sonar();if(action&&Mathf.Abs(ballast)<.01f){if(d.Carrying!=null)d.Drop();else if(!d.GrabNearest())d.Sonar();}}
    d.Pilot(drive,vertical,ballast,roll,dt);
   }
  }
  void ReadControls(int slot,out float vertical,out float ballast,out float roll,out bool sonar){vertical=ballast=roll=0;sonar=false;var p=setup.players[slot];if(!p.released||!Ready(slot))return;if(p.source==BowlingSource.Keyboard){vertical=(SportsDeviceInput.KeyHeld(ascendKeys[slot])?1:0)-(SportsDeviceInput.KeyHeld(descendKeys[slot])?1:0);bool modifier=SportsDeviceInput.KeyHeld(sonarKeys[slot]);sonar=modifier&&vertical==0;if(modifier&&vertical!=0){ballast=-vertical;vertical=0;}return;}if(!p.Controller)return;var pad=p.pad;if(p.source==BowlingSource.WholeController){vertical=(pad.rightShoulder.isPressed?1:0)-(pad.leftShoulder.isPressed?1:0);ballast=pad.dpad.ReadValue().y;roll=pad.dpad.ReadValue().x;sonar=pad.buttonWest.isPressed;}else{bool right=p.source==BowlingSource.RightStick;vertical=((right?pad.rightShoulder:pad.leftShoulder).isPressed?1:0)-((right?pad.rightStickButton:pad.leftStickButton).isPressed?1:0);if(ActionHeld(slot)&&vertical!=0){ballast=-vertical;vertical=0;}}}
  Vector2 Bot(int slot,float dt,out float vertical){var diver=divers[slot];var truck=diver.truck;var position=truck.body.position;if(rules.Clock>=nextPlan[slot]){nextPlan[slot]=rules.Clock+.35f;AIPlans++;Vector3 goal;if(diver.Carrying!=null){target[slot]=-1;goal=buoy.reception.bounds.center-Vector3.up;}else{int best=-1;float cost=float.MaxValue;foreach(var cargo in treasures){if(!rules.Available(cargo.id)||!diver.discovered[cargo.id]||cargo.OriginalDepth>rules.RatedDepth+4)continue;float score=(cargo.body.position-position).sqrMagnitude/SubmarineRules.Value(cargo.kind,cargo.OriginalDepth);if(score<cost){cost=score;best=cargo.id;}}target[slot]=best;if(best>=0)goal=treasures[best].body.position-Vector3.up;else{goal=Patrol[patrol[slot]];goal.y=Mathf.Max(goal.y,-rules.RatedDepth+8);if(Vector3.Distance(goal,position)<16)patrol[slot]=(patrol[slot]+1)%Patrol.Length;}}if(-position.y>rules.RatedDepth-2||rules.integrity[slot]<35)goal=new Vector3(position.x,-Mathf.Min(45,rules.RatedDepth-20),position.z+10);goals[slot]=goal;}
   var delta=goals[slot]-position;var planar=Vector3.ProjectOnPlane(delta,Vector3.up);float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(truck.transform.forward,Vector3.up),planar,Vector3.up);vertical=Mathf.Clamp(delta.y*.25f-truck.body.linearVelocity.y*.35f,-1,1);float throttle=planar.magnitude<4?0:Mathf.Clamp(planar.magnitude*.12f,.15f,1)*Mathf.Lerp(.25f,1,1-Mathf.Clamp01(Mathf.Abs(angle)/100));float steer=Mathf.Clamp(angle/45,-1,1);var direction=delta.normalized;int count=Physics.SphereCastNonAlloc(position+Vector3.up,2,direction,obstacles,12,1,QueryTriggerInteraction.Ignore);for(int j=0;j<count;j++){var hit=obstacles[j];if(hit.collider.transform.IsChildOf(truck.transform)||hit.normal.y>.75f)continue;if(hit.distance<9){vertical=Mathf.Max(vertical,.8f);steer+=Vector3.Dot(hit.normal,truck.transform.right)*.7f;throttle*=.5f;break;}}return new Vector2(Mathf.Clamp(steer,-1,1),throttle);
  }
  public bool Deliver(SubmarineCargo cargo,int slot){if(!Live||cargo==null||cargo.match!=this||slot<0||slot>=setup.count||divers[slot].Carrying!=cargo||cargo.Owner!=slot||!buoy.reception.bounds.Contains(cargo.body.worldCenterOfMass))return false;int delta=rules.Bank(slot,cargo.id,cargo.kind,cargo.OriginalDepth);if(delta<=0)return false;divers[slot].Delivered(cargo);cargo.RetireDelivered();NativeDeliveries++;LastDeliveredOwner=slot;ConfirmScore("delivered:"+cargo.id,slot,delta,rules.points[slot],cargo.kind.ToString().ToUpperInvariant()+" DELIVERED",delta>=100?SportsScoreTier.Major:SportsScoreTier.Small);feedback.PlayAt(3,buoy.transform.position,0,true);Pulse(slot,.3f,.15f);presentation.Delivery(slot,delta);return true;}
  public override void DescribeBroadcast(SportsBroadcastAction action,SportsBroadcastFraming source){int owner=LastDeliveredOwner>=0&&!rules.retired[LastDeliveredOwner]?LastDeliveredOwner:source.Nearest(buoy.transform.position,true);if(owner<0)owner=source.Nearest(buoy.transform.position);action.primary=owner;Vector3 point=owner>=0?divers[owner].truck.body.position:buoy.transform.position;if(owner>=0&&divers[owner].Carrying!=null&&Vector3.Distance(point,buoy.transform.position)<65)point=buoy.transform.position;else if(owner>=0&&target[owner]>=0&&Vector3.Distance(point,treasures[target[owner]].body.position)<65)point=treasures[target[owner]].body.position;action.Objective(point,5);action.reason="ACTUAL DIVER / PHYSICAL TREASURE / SCORING BUOY";}
  protected override void Present(float dt){if(!Running||drivingViews==null)return;drivingViews.Tick(dt);if(drivingViews.NeedsArena&&broadcast.LegacyPoseAllowed){int slot=LastDeliveredOwner>=0?LastDeliveredOwner:0;var p=divers[slot].truck.body.position;broadcast.Pose(p,new Vector3(0,20,-32),60);}presentation.Tick(dt);}
  public override void ExtraAction(string key){if(key=="drivingview")drivingViews.Cycle();}
  protected override void SetPaused(bool paused){presentation?.Pause(paused);}
  protected override void StopSounds(){if(divers!=null)foreach(var d in divers)if(d!=null)d.truck.StopSound();presentation?.StopSound();}
  protected override void StopGame(){if(divers!=null)foreach(var d in divers)if(d!=null)d.Freeze();if(treasures!=null)foreach(var cargo in treasures)if(cargo!=null)cargo.Freeze();StopSounds();}
 }
}
